// Perspective floor and camera-facing sprites share the same 3D projection.
window.ArenaArt=(function(){
const C=window.Fight,P=C.project;
function polygon(ctx,points,color,stroke){ctx.beginPath();points.forEach((v,i)=>{const p=P(v[0],v[2],v[1]);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)});ctx.closePath();if(color){ctx.fillStyle=color;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function line(ctx,a,b,color,width=2){const p=P(a[0],a[2],a[1]),q=P(b[0],b[2],b[1]);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}
function circle(ctx,x,z,r,color,fill=false){ctx.beginPath();for(let i=0;i<=40;i++){const a=i/40*Math.PI*2,p=P(x+Math.cos(a)*r,z+Math.sin(a)*r,1);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=2;if(fill){ctx.fillStyle=color;ctx.fill()}else ctx.stroke()}
function strikeArc(ctx,x,z,aim,r,color,fill=false,angleWidth=1.47){const angle=Math.atan2(aim.z,aim.x),center=P(x,z,2);ctx.beginPath();ctx.moveTo(center.x,center.y);for(let i=0;i<=16;i++){const a=angle-angleWidth+i*angleWidth*2/16,p=P(x+Math.cos(a)*r,z+Math.sin(a)*r,2);ctx.lineTo(p.x,p.y)}ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=2;if(fill){ctx.fillStyle=color;ctx.fill()}else ctx.stroke()}
function box(ctx,x,z,w,h,d,colors){polygon(ctx,[[x-w/2,0,z+d/2],[x+w/2,0,z+d/2],[x+w/2,h,z+d/2],[x-w/2,h,z+d/2]],colors[0]);polygon(ctx,[[x+w/2,0,z+d/2],[x+w/2,0,z-d/2],[x+w/2,h,z-d/2],[x+w/2,h,z+d/2]],colors[1]);polygon(ctx,[[x-w/2,h,z-d/2],[x+w/2,h,z-d/2],[x+w/2,h,z+d/2],[x-w/2,h,z+d/2]],colors[2])}
function floor(ctx,b,time){const gym=b.encounter.kind==='gym',biome=b.encounter.biome,sand=biome==='desierto'||biome==='costa',stone=biome==='montaña',bg=ctx.createLinearGradient(0,0,0,540);bg.addColorStop(0,gym?'#29443f':sand?'#c5bd9b':'#7caa9a');bg.addColorStop(1,gym?'#688575':'#d1d7b1');ctx.fillStyle=bg;ctx.fillRect(0,0,960,540);
if(gym){polygon(ctx,[[-640,0,-420],[640,0,-420],[640,270,-420],[-640,270,-420]],'#355b50');for(let x=-600;x<700;x+=200)box(ctx,x,-405,28,250,35,['#58766a','#314e47','#abc5a0']);const banner=P(0,-415,180);ctx.textAlign='center';ctx.fillStyle='#e1dfb2';ctx.font='bold 18px monospace';ctx.fillText('GIMNASIO BROTE',banner.x,banner.y);ctx.font='10px monospace';ctx.fillText('VERA · ARENA ABIERTA',banner.x,banner.y+18)}else{ctx.fillStyle='#8ba485';ctx.beginPath();ctx.moveTo(0,220);for(let x=0;x<=960;x+=60)ctx.lineTo(x,154-Math.sin(x/180)*35);ctx.lineTo(960,280);ctx.lineTo(0,280);ctx.fill()}
for(let z=-420;z<430;z+=70)for(let x=-630;x<650;x+=70){const alt=(Math.round(x/70)+Math.round(z/70))%2===0,color=gym?(alt?'#829783':'#8b9d86'):sand?(alt?'#c2b583':'#c9bb8b'):stone?(alt?'#97a79b':'#a2b0a0'):(alt?'#88a675':'#90ac7b');polygon(ctx,[[x,0,z],[x+70,0,z],[x+70,0,z+70],[x,0,z+70]],color,gym?'#b8c6a041':null);if(!gym){const p=P(x+25,z+32);ctx.fillStyle=sand?'#ac9e6b55':'#4b734431';ctx.fillRect(p.x,p.y,Math.max(2,8*p.scale),2)}}
line(ctx,[-C.ARENA.halfX,1,-C.ARENA.halfZ],[C.ARENA.halfX,1,-C.ARENA.halfZ],'#d8e2b7',3);line(ctx,[C.ARENA.halfX,1,-C.ARENA.halfZ],[C.ARENA.halfX,1,C.ARENA.halfZ],'#d8e2b7',3);line(ctx,[C.ARENA.halfX,1,C.ARENA.halfZ],[-C.ARENA.halfX,1,C.ARENA.halfZ],'#d8e2b7',3);line(ctx,[-C.ARENA.halfX,1,C.ARENA.halfZ],[-C.ARENA.halfX,1,-C.ARENA.halfZ],'#d8e2b7',3);circle(ctx,0,0,100,'#d3dfb687');line(ctx,[-100,1,0],[100,1,0],'#d3dfb687');circle(ctx,0,0,20,'#d3dfb687');
if(b.result)return;ctx.fillStyle='#254c36b8';ctx.fillRect(344,496,272,25);ctx.fillStyle='#eaf0d7';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('ARENA 3D · MUEVE EN TODAS DIRECCIONES',480,512)}
function telegraph(ctx,a,m,time){const color=window.Frontera.TYPE[m.type]?.[1]||'#d9d9aa';ctx.save();ctx.globalAlpha=.25+.3*(1-m.time/m.total);if(m.kind==='melee'||m.kind==='lunge')strikeArc(ctx,a.x,a.z,m.aim,C.meleeReach(m),color,true,m.key?1.47:Math.PI/3);else if(m.kind==='targetArea')circle(ctx,m.targetX,m.targetZ,m.areaRadius,color,true);else if(m.kind==='area'||m.kind==='self')circle(ctx,a.x,a.z,m.kind==='self'?60:m.range,color,true);else if(m.kind==='beam'){const v=m.aim,n={x:-v.z,z:v.x},w=m.width||22;polygon(ctx,[[a.x+n.x*w,1,a.z+n.z*w],[a.x-n.x*w,1,a.z-n.z*w],[a.x+v.x*m.range-n.x*w,1,a.z+v.z*m.range-n.z*w],[a.x+v.x*m.range+n.x*w,1,a.z+v.z*m.range+n.z*w]],color)}else{circle(ctx,a.x,a.z,m.kind==='cone'?m.range:70,color);line(ctx,[a.x,2,a.z],[a.x+m.aim.x*Math.min(m.range,200),2,a.z+m.aim.z*Math.min(m.range,200)],color,3)}ctx.restore()}
function effect(ctx,e){ctx.save();ctx.globalAlpha=Math.max(0,e.time/e.total)*.7;const v=e.aim||{x:1,z:0},p=P(e.x,e.z,35),q=P(e.x+v.x*e.range,e.z+v.z*e.range,35);if(e.kind==='beam'){ctx.strokeStyle=e.color;ctx.lineWidth=e.visual==='water'?14:6;ctx.beginPath();ctx.moveTo(p.x,p.y);if(e.visual==='electric'){for(let i=1;i<8;i++)ctx.lineTo(p.x+(q.x-p.x)*i/8+Math.sin(i*13)*8,p.y+(q.y-p.y)*i/8+Math.cos(i*7)*5)}ctx.lineTo(q.x,q.y);ctx.stroke();ctx.strokeStyle='#fff8';ctx.lineWidth=2;ctx.stroke()}else if(e.kind==='cone'){const n={x:-v.z,z:v.x};polygon(ctx,[[e.x,20,e.z],[e.x+v.x*e.range+n.x*e.range*.65,20,e.z+v.z*e.range+n.z*e.range*.65],[e.x+v.x*e.range-n.x*e.range*.65,20,e.z+v.z*e.range-n.z*e.range*.65]],e.color)}else if(e.kind==='targetArea'){circle(ctx,e.targetX,e.targetZ,e.radius,e.color,true);for(let i=0;i<5;i++)box(ctx,e.targetX+Math.sin(i*7)*65,e.targetZ+Math.cos(i*7)*60,22,20+25*e.time/e.total,25,['#a2a99b','#687b6e','#d4d4b3'])}else if(e.kind==='area'||e.kind==='self')circle(ctx,e.x,e.z,e.kind==='self'?70:e.range,e.color);else if(e.kind==='melee'||e.kind==='lunge'){strikeArc(ctx,e.x,e.z,v,e.range,e.color,false,e.contactAngle);const contact=P(e.x+v.x*e.range*.55,e.z+v.z*e.range*.55,35);ctx.strokeStyle=e.color;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(contact.x-18,contact.y+4);ctx.lineTo(contact.x+20,contact.y-27);ctx.moveTo(contact.x-10,contact.y+8);ctx.lineTo(contact.x+28,contact.y-22);ctx.stroke()}ctx.restore()}
function shot(ctx,s,time){const p=P(s.x,s.z,s.y),r=(s.m.radius||18)*p.scale;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle=s.color;ctx.strokeStyle='#fff9';ctx.lineWidth=2;switch(s.visual){case'leaf':ctx.rotate(time*9);ctx.beginPath();ctx.ellipse(0,0,r,r*.4,0,0,Math.PI*2);ctx.fill();ctx.stroke();break;case'ice':ctx.rotate(time*2);ctx.beginPath();ctx.moveTo(0,-r);ctx.lineTo(r*.55,0);ctx.lineTo(0,r);ctx.lineTo(-r*.55,0);ctx.closePath();ctx.fill();ctx.stroke();break;case'bone':ctx.rotate(time*7);ctx.fillRect(-r,-3,r*2,6);for(const x of [-r,r]){ctx.beginPath();ctx.arc(x,-3,4,0,Math.PI*2);ctx.arc(x,3,4,0,Math.PI*2);ctx.fill()}break;case'psychic':ctx.rotate(time*4);ctx.beginPath();ctx.ellipse(0,0,r,r*.65,0,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(0,0,r*.4,0,Math.PI*2);ctx.fill();break;case'needle':ctx.rotate(Math.atan2(s.vz,s.vx));ctx.fillRect(-r,-2,r*2,4);break;case'rock':case'metal':case'coin':ctx.rotate(time*5);ctx.fillRect(-r*.6,-r*.6,r*1.2,r*1.2);ctx.strokeRect(-r*.6,-r*.6,r*1.2,r*1.2);break;case'bubble':ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.stroke();break;case'sleep':case'ghost':ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#fff9';ctx.fillRect(-r/3,-3,3,5);ctx.fillRect(r/3,-3,3,5);break;default:ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff9';ctx.beginPath();ctx.arc(-3,-4,r*.3,0,Math.PI*2);ctx.fill()}ctx.restore()}
return{floor,circle,telegraph,effect,shot};
})();
